export type ParsedSampleLiquidityV4Instruction<
  TProgram extends string = typeof CLEARING_PROGRAM_ADDRESS,
  TAccountMetas extends readonly AccountMeta[] = readonly AccountMeta[],
> = {
  programAddress: Address<TProgram>;
  accounts: {
    payer: TAccountMetas[0];
    venue: TAccountMetas[1];
    custody: TAccountMetas[2];
    safety: TAccountMetas[3];
    market: TAccountMetas[4];
    registry: TAccountMetas[5];
    primaryAsset: TAccountMetas[6];
    primaryCollateral: TAccountMetas[7];
    guardAsset: TAccountMetas[8];
    guardCollateral: TAccountMetas[9];
    firstCapital: TAccountMetas[10];
    firstRegistration: TAccountMetas[11];
    firstProgram: TAccountMetas[12];
    firstProgramData: TAccountMetas[13];
    firstConfig: TAccountMetas[14];
    firstPrice: TAccountMetas[15];
    secondCapital: TAccountMetas[16];
    secondRegistration: TAccountMetas[17];
    secondProgram: TAccountMetas[18];
    secondProgramData: TAccountMetas[19];
    secondConfig: TAccountMetas[20];
    secondPrice: TAccountMetas[21];
    thirdCapital: TAccountMetas[22];
    thirdRegistration: TAccountMetas[23];
    thirdProgram: TAccountMetas[24];
    thirdProgramData: TAccountMetas[25];
    thirdConfig: TAccountMetas[26];
    thirdPrice: TAccountMetas[27];
    eventAuthority: TAccountMetas[28];
    program: TAccountMetas[29];
  };
  data: SampleLiquidityV4InstructionData;
};

export function parseSampleLiquidityV4Instruction<
  TProgram extends string,
  TAccountMetas extends readonly AccountMeta[],
>(
  instruction: Instruction<TProgram> &
    InstructionWithAccounts<TAccountMetas> &
    InstructionWithData<ReadonlyUint8Array>,
): ParsedSampleLiquidityV4Instruction<TProgram, TAccountMetas> {
  if (instruction.accounts.length < 30) {
    throw new SolanaError(
      SOLANA_ERROR__PROGRAM_CLIENTS__INSUFFICIENT_ACCOUNT_METAS,
      {
        actualAccountMetas: instruction.accounts.length,
        expectedAccountMetas: 30,
      },
    );
  }
  let accountIndex = 0;
  const getNextAccount = () => {
    const accountMeta = (instruction.accounts as TAccountMetas)[accountIndex]!;
    accountIndex += 1;
    return accountMeta;
  };
  return {
    programAddress: instruction.programAddress,
    accounts: {
      payer: getNextAccount(),
      venue: getNextAccount(),
      custody: getNextAccount(),
      safety: getNextAccount(),
      market: getNextAccount(),
      registry: getNextAccount(),
      primaryAsset: getNextAccount(),
      primaryCollateral: getNextAccount(),
      guardAsset: getNextAccount(),
      guardCollateral: getNextAccount(),
      firstCapital: getNextAccount(),
      firstRegistration: getNextAccount(),
      firstProgram: getNextAccount(),
      firstProgramData: getNextAccount(),
      firstConfig: getNextAccount(),
      firstPrice: getNextAccount(),
      secondCapital: getNextAccount(),
      secondRegistration: getNextAccount(),
      secondProgram: getNextAccount(),
      secondProgramData: getNextAccount(),
      secondConfig: getNextAccount(),
      secondPrice: getNextAccount(),
      thirdCapital: getNextAccount(),
      thirdRegistration: getNextAccount(),
      thirdProgram: getNextAccount(),
      thirdProgramData: getNextAccount(),
      thirdConfig: getNextAccount(),
      thirdPrice: getNextAccount(),
      eventAuthority: getNextAccount(),
      program: getNextAccount(),
    },
    data: getSampleLiquidityV4InstructionDataDecoder().decode(instruction.data),
  };
}
